const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Africa boundary
  var africa = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('wld_rgn', 'Africa'));

  // Get MODIS Land Cover data
  var modis2004_2007 = ee.ImageCollection('MODIS/006/MCD12Q1')
    .filterDate('2004-01-01', '2007-12-31')
    .filterBounds(africa);

  var modis2016_2019 = ee.ImageCollection('MODIS/006/MCD12Q1')
    .filterDate('2016-01-01', '2019-12-31')
    .filterBounds(africa);

  // Check collection sizes
  var size1 = modis2004_2007.size().getInfo();
  var size2 = modis2016_2019.size().getInfo();

  print(`2004-2007 Images: ${size1}`);
  print(`2016-2019 Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    print("<answer>C1</answer>");
    return;
  }

  // Get first and last images for each period
  var first2004 = modis2004_2007.filterDate('2004-01-01', '2004-12-31').first();
  var last2007 = modis2004_2007.filterDate('2007-01-01', '2007-12-31').first();
  var first2016 = modis2016_2019.filterDate('2016-01-01', '2016-12-31').first();
  var last2019 = modis2016_2019.filterDate('2019-01-01', '2019-12-31').first();

  // Define cropland class (12 = croplands in IGBP classification)
  var croplandClass = 12;

  // Calculate cropland areas in km²
  var area2004 = first2004.eq(croplandClass).multiply(ee.Image.pixelArea().divide(1000000))
    .reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: africa,
      scale: 1000,
      maxPixels: 1e9
    }).get('LC_Type1').getInfo();

  var area2007 = last2007.eq(croplandClass).multiply(ee.Image.pixelArea().divide(1000000))
    .reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: africa,
      scale: 1000,
      maxPixels: 1e9
    }).get('LC_Type1').getInfo();

  var area2016 = first2016.eq(croplandClass).multiply(ee.Image.pixelArea().divide(1000000))
    .reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: africa,
      scale: 1000,
      maxPixels: 1e9
    }).get('LC_Type1').getInfo();

  var area2019 = last2019.eq(croplandClass).multiply(ee.Image.pixelArea().divide(1000000))
    .reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: africa,
      scale: 1000,
      maxPixels: 1e9
    }).get('LC_Type1').getInfo();

  // Check for valid pixels
  if (area2004 === null || area2007 === null || area2016 === null || area2019 === null) {
    print("<answer>C2</answer>");
    return;
  }

  // Calculate annual expansion rates
  var rate2004_2007 = (area2007 - area2004) / 3; // 3 years between start and end
  var rate2016_2019 = (area2019 - area2016) / 3;

  print(`2004 Cropland: ${area2004.toFixed(0)} km²`);
  print(`2007 Cropland: ${area2007.toFixed(0)} km²`);
  print(`2016 Cropland: ${area2016.toFixed(0)} km²`);
  print(`2019 Cropland: ${area2019.toFixed(0)} km²`);
  print(`2004-2007 Rate: ${rate2004_2007.toFixed(0)} km²/yr`);
  print(`2016-2019 Rate: ${rate2016_2019.toFixed(0)} km²/yr`);

  // Check for calculation failures
  if (!isFinite(rate2004_2007) || !isFinite(rate2016_2019)) {
    print("<answer>C3</answer>");
    return;
  }

  // Determine if expansion slowed
  if (rate2016_2019 < rate2004_2007) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
